{
  "description": "The creature is a quadrupedal, bear-bodied animal shown in right-facing profile against a plain off-white background. Its head, ears, and paws are those of a brown bear with dense brown fur, a lighter tan muzzle, and dark claws, while the entire neck, back, sides, and outer surfaces of the legs and tail are covered in a glossy, black, segmented exoskeleton of overlapping hard plates. A single large, glossy black, sickle-shaped horn with two small thorn-like points on its inner curve rises from a plate on the forehead and curves backward then forward over the head. The body is low and stout, standing on four thick legs, with a short, pointed, armored tail hanging down at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a paler tan muzzle and lower cheek, a black nose at the tip of the snout, small brown eyes, and a closed mouth with a hint of lower lip, located at the front of the body facing to the right",
      "where": "at the anterior end of the body, attached to the armored neck"
    },
    {
      "part": "horns",
      "looks_like": "a single large glossy black horn, smooth and curved like a sickle with two small pointed projections on the concave inner edge and a segmented ringed base where it meets the head plate",
      "where": "rising from the center of a black plate on the top of the head between the ears, arching up and backward then forward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in fluffy brown fur, with the inner ear barely visible",
      "where": "on the sides of the head just behind and to either side of the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, stout legs encased in glossy black overlapping plates on the upper and outer surfaces, with exposed brown fur and wrinkled skin at the joints near the paws",
      "where": "two forelegs under the chest and two hindlegs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear-like paws with brown fur on top and five long, curved, light-tipped claws on each paw",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, tapering, armored tail covered in small overlapping glossy black plates ending in a pointed tip",
      "where": "at the posterior end of the body, hanging down from the rear of the dorsal armor"
    },
    {
      "part": "plates",
      "looks_like": "an extensive glossy black exoskeleton of large overlapping transverse dorsal plates covering the back from neck to tail, smaller overlapping plates on the sides, neck, and legs, and rows of oval openings along the lower sides of the back and neck",
      "where": "covering the dorsal surface, sides, neck, and most of the legs, leaving only the head, ears, joint fur, paws, and tail tip exposed"
    },
    {
      "part": "shell",
      "looks_like": "the same glossy black segmented carapace forming a continuous hard covering over the back and sides, with a slightly raised, domed profile and visible sutures between plates",
      "where": "over the entire trunk from just behind the head to the base of the tail"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle",
    "isopod"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
